import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  JoinColumn,
} from 'typeorm';
import { User } from '../../users/entities/user.entity';
import { Model } from '../../models/entities/model.entity';
import { ApiKeyType } from '../enums/api-key-type.enum';

/**
 * Entity representing an API secret key used for programmatically authenticating model predictions.
 */
@Entity('api_keys')
export class ApiKey {
  /**
   * Unique UUID identifier generated by the database.
   */
  @PrimaryGeneratedColumn('uuid')
  id: string;

  /**
   * Cryptographically secure secret key string, prefixed with 'ml_sk_live_'.
   */
  @Column({ unique: true })
  key: string;

  /**
   * A user-friendly nickname for this token (e.g. 'Default Key').
   */
  @Column({ default: 'Default Key' })
  name: string;

  /**
   * The User owner who generated and holds this API credential.
   */
  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user: User;

  /**
   * The specific Model this API credential authorizes access to.
   */
  @ManyToOne(() => Model, { onDelete: 'CASCADE', nullable: true })
  @JoinColumn({ name: 'model_id' })
  model: Model | null;

  /**
   * The classification of key (LIVE for production, TRIAL for sandbox playground).
   */
  @Column({
    type: 'varchar',
    enum: ApiKeyType,
    default: ApiKeyType.LIVE,
  })
  type: ApiKeyType;

  /**
   * Usage limit counter tracking executions on sandbox trial keys.
   */
  @Column({ name: 'calls_count', type: 'integer', default: 0 })
  callsCount: number;

  /**
   * Activation status. Toggled off if revoked.
   */
  @Column({ name: 'is_active', default: true })
  isActive: boolean;

  /**
   * Optional expiration date. Null represents a non-expiring credential.
   */
  @Column({
    name: 'expires_at',
    type: 'timestamp with time zone',
    nullable: true,
  })
  expiresAt: Date | null;

  /**
   * Maximum number of prediction requests this key may make per minute.
   * Null means no rate limit is enforced.
   */
  @Column({ name: 'max_requests_per_minute', type: 'integer', nullable: true })
  maxRequestsPerMinute: number | null;

  /**
   * Maximum credits this key may spend per calendar day. Once reached, the
   * key is automatically suspended (`isActive` set to false).
   * Null means no budget cap is enforced.
   */
  @Column({
    name: 'max_daily_spend_credits',
    type: 'decimal',
    precision: 12,
    scale: 4,
    nullable: true,
  })
  maxDailySpendCredits: number | null;

  /**
   * Explains why the key was automatically suspended by quota enforcement,
   * distinct from a manual owner revocation.
   */
  @Column({ name: 'suspended_reason', type: 'varchar', nullable: true })
  suspendedReason: string | null;

  /**
   * Timestamp record indicating when this key was originally created.
   */
  @CreateDateColumn({ name: 'created_at' })
  createdAt: Date;

  /**
   * Timestamp record indicating when this key settings were last modified.
   */
  @UpdateDateColumn({ name: 'updated_at' })
  updatedAt: Date;
}
